insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('cd000000-0000-0000-0000-000000000001', 'ukmla', 'ededac06-c50e-4602-8f0a-0c1be1c97e4f',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('cd000000-0000-0000-0000-000000000001', 'A', 'Reassure and arrange routine antenatal review in one week', false, 'Ruled out because severe pre-eclampsia with clonus and organ dysfunction is an obstetric emergency requiring immediate admission, not deferred routine review.', 1),
('cd000000-0000-0000-0000-000000000001', 'B', 'Oral labetalol only, then discharge home with community midwife follow-up', false, 'Ruled out because severe features (clonus, thrombocytopenia, deranged LFTs) mean she needs admission, IV treatment and seizure prophylaxis, not outpatient management.', 2),
('cd000000-0000-0000-0000-000000000001', 'C', 'Start oral nifedipine and repeat bloods in 48 hours as an outpatient', false, 'Ruled out because clonus signals impending eclampsia; this cannot safely be managed as an outpatient with delayed blood monitoring.', 3),
('cd000000-0000-0000-0000-000000000001', 'D', 'Immediate caesarean section without administering magnesium sulfate first', false, 'Ruled out because maternal stabilisation, including magnesium sulfate for seizure prophylaxis and BP control, should occur before proceeding to delivery wherever possible.', 4),
('cd000000-0000-0000-0000-000000000001', 'E', 'IV magnesium sulfate, antihypertensive treatment (e.g. IV labetalol), and urgent obstetric assessment for delivery', true, 'Correct. Severe headache, epigastric pain, severe hypertension, clonus, thrombocytopenia and deranged liver function indicate severe pre-eclampsia with impending eclampsia. Magnesium sulfate prevents/treats seizures, BP must be controlled, and delivery is the definitive treatment once the mother is stabilised.', 5),
('cd000000-0000-0000-0000-000000000002', 'A', 'The fasting glucose of 5.8 mmol/L alone is diagnostic, as it exceeds the fasting threshold of 5.6 mmol/L', true, 'Correct. Diagnostic thresholds for gestational diabetes are fasting glucose 5.6 mmol/L or above, or 2-hour glucose 7.8 mmol/L or above; only one abnormal value is required to make the diagnosis, and her fasting value meets this.', 1),
('cd000000-0000-0000-0000-000000000002', 'B', 'Neither value is diagnostic because both thresholds must be exceeded simultaneously', false, 'Ruled out because only one abnormal value (fasting or 2-hour) is required for diagnosis, not both together.', 2),
('cd000000-0000-0000-0000-000000000002', 'C', 'The diagnosis requires a fasting glucose above 7.0 mmol/L, so this patient does not have gestational diabetes', false, 'Ruled out because 7.0 mmol/L is the diagnostic threshold used outside pregnancy; the pregnancy-specific fasting threshold is lower, at 5.6 mmol/L.', 3),
('cd000000-0000-0000-0000-000000000002', 'D', 'The 2-hour glucose of 7.2 mmol/L confirms gestational diabetes because it is elevated', false, 'Ruled out because 7.2 mmol/L is below the 2-hour diagnostic threshold of 7.8 mmol/L, so this value alone is not diagnostic.', 4),
('cd000000-0000-0000-0000-000000000002', 'E', 'A repeat OGTT is required in two weeks before any diagnosis can be made', false, 'Ruled out because the diagnosis can be confirmed from this result; a repeat test is unnecessary delay.', 5),
('cd000000-0000-0000-0000-000000000003', 'A', 'Reassure and remeasure symphysis-fundal height in four weeks at the next routine visit', false, 'Ruled out because this discrepancy is significant and delaying assessment risks missing evolving fetal growth restriction.', 1),
('cd000000-0000-0000-0000-000000000003', 'B', 'Referral for ultrasound growth scan with umbilical artery Doppler', true, 'Correct. A symphysis-fundal height more than 3cm below that expected for gestation warrants referral for ultrasound assessment of fetal growth and Doppler studies to assess placental function.', 2),
('cd000000-0000-0000-0000-000000000003', 'C', 'Arrange induction of labour immediately given suspected growth restriction', false, 'Ruled out because induction is premature before confirming the diagnosis and severity with ultrasound; management depends on scan findings.', 3),
('cd000000-0000-0000-0000-000000000003', 'D', 'Advise increased oral intake and recheck symphysis-fundal height in two weeks', false, 'Ruled out because there is no evidence that maternal dietary intake corrects fetal growth restriction, and this delays proper assessment.', 4),
('cd000000-0000-0000-0000-000000000003', 'E', 'Refer for amniocentesis to assess for chromosomal abnormality', false, 'Ruled out because amniocentesis is not indicated on the basis of an isolated symphysis-fundal height discrepancy without other suggestive features.', 5),
('cd000000-0000-0000-0000-000000000004', 'A', 'Perform a digital vaginal examination to assess cervical dilatation', false, 'Ruled out because digital examination is contraindicated in suspected placenta praevia until the placental location has been confirmed.', 1),
('cd000000-0000-0000-0000-000000000004', 'B', 'Discharge home with reassurance as the bleeding has stopped', false, 'Ruled out because admission for observation is required given the risk of further bleeding with placenta praevia.', 2),
('cd000000-0000-0000-0000-000000000004', 'C', 'Arrange immediate caesarean section regardless of examination findings', false, 'Ruled out because immediate delivery is not required while mother and fetus remain stable; management depends on further assessment and gestation.', 3),
('cd000000-0000-0000-0000-000000000004', 'D', 'Admit for observation and arrange transvaginal ultrasound to localise the placenta, avoiding digital vaginal examination', true, 'Correct. Painless bleeding with a known low-lying placenta suggests placenta praevia; digital vaginal examination is avoided until placental location is confirmed, as it can provoke catastrophic haemorrhage.', 4),
('cd000000-0000-0000-0000-000000000004', 'E', 'Administer anti-D immunoglobulin only, with no further assessment required', false, 'Ruled out because anti-D (if Rhesus negative) addresses sensitisation risk but does not address the need to localise the placenta and monitor for further bleeding.', 5),
('cd000000-0000-0000-0000-000000000005', 'A', 'Withhold anti-D as she has had no sensitising events', false, 'Ruled out because routine antenatal anti-D prophylaxis is given regardless of whether a specific sensitising event has occurred.', 1),
('cd000000-0000-0000-0000-000000000005', 'B', 'Anti-D is unnecessary because she is Rhesus negative, not Rhesus positive', false, $x$Ruled out because being Rhesus negative is precisely why anti-D is needed, to prevent her forming antibodies against a Rhesus-positive fetus's red cells.$x$, 2),
('cd000000-0000-0000-0000-000000000005', 'C', 'Routine antenatal anti-D immunoglobulin prophylaxis', true, 'Correct. Rhesus-negative women without antibodies receive routine antenatal anti-D prophylaxis (commonly around 28 weeks) to reduce the risk of sensitisation to fetal Rh-positive cells.', 3),
('cd000000-0000-0000-0000-000000000005', 'D', 'Delay anti-D administration until after delivery only', false, 'Ruled out because antenatal anti-D prophylaxis during pregnancy is also required, in addition to postnatal anti-D if the baby is Rh-positive.', 4),
('cd000000-0000-0000-0000-000000000005', 'E', $x$Test the father's blood group before deciding on anti-D$x$, false, 'Ruled out because in practice routine antenatal prophylaxis is given to Rhesus-negative women regardless of paternal blood group testing.', 5),
('cd000000-0000-0000-0000-000000000006', 'A', 'Reassure and advise her to return only if movements stop completely', false, 'Ruled out because reduced fetal movements require prompt assessment; waiting for complete cessation risks missing an evolving problem.', 1),
('cd000000-0000-0000-0000-000000000006', 'B', 'Arrange induction of labour immediately', false, 'Ruled out because induction is premature without first assessing fetal wellbeing with CTG (and ultrasound if indicated).', 2),
('cd000000-0000-0000-0000-000000000006', 'C', 'Cardiotocography to assess the fetal heart rate pattern', true, 'Correct. CTG is the appropriate first-line assessment of fetal wellbeing for reduced fetal movements after 28 weeks gestation.', 3),
('cd000000-0000-0000-0000-000000000006', 'D', 'Amniocentesis to test the amniotic fluid for infection', false, 'Ruled out because this is not an appropriate or indicated investigation for reduced fetal movements.', 4),
('cd000000-0000-0000-0000-000000000006', 'E', 'Advise bed rest lying on her left side for 48 hours before reassessment', false, 'Ruled out because this delays the necessary immediate assessment of fetal wellbeing.', 5),
('cd000000-0000-0000-0000-000000000007', 'A', 'Arrange an outpatient transvaginal ultrasound scan within 24 hours', false, 'Ruled out because this delay is unsafe in a haemodynamically unstable patient with suspected rupture; assessment and treatment must be immediate.', 1),
('cd000000-0000-0000-0000-000000000007', 'B', 'Discharge with oral analgesia and advice to return if pain worsens', false, 'Ruled out because this is dangerously unsafe given signs of hypovolaemic shock.', 2),
('cd000000-0000-0000-0000-000000000007', 'C', 'Start methotrexate therapy in the emergency department', false, 'Ruled out because methotrexate is contraindicated in a ruptured or haemodynamically unstable ectopic pregnancy, which requires surgery, not medical management.', 3),
('cd000000-0000-0000-0000-000000000007', 'D', 'Perform a pelvic examination only, then reassess in four hours', false, 'Ruled out because this delays lifesaving resuscitation and surgical intervention.', 4),
('cd000000-0000-0000-0000-000000000007', 'E', 'Urgent gynaecology referral for emergency laparoscopy, with resuscitation (IV fluids, group and save/crossmatch) commenced immediately', true, 'Correct. Sudden severe unilateral pain, tachycardia and hypotension with a positive pregnancy test suggest a ruptured ectopic pregnancy, a surgical emergency requiring resuscitation and urgent surgery.', 5),
('cd000000-0000-0000-0000-000000000008', 'A', 'Threatened miscarriage', true, 'Correct. Vaginal bleeding in early pregnancy with a closed cervix and a confirmed viable intrauterine pregnancy on ultrasound defines a threatened miscarriage.', 1),
('cd000000-0000-0000-0000-000000000008', 'B', 'Inevitable miscarriage', false, 'Ruled out because the cervix is closed here; an inevitable miscarriage is characterised by an open cervix.', 2),
('cd000000-0000-0000-0000-000000000008', 'C', 'Missed miscarriage', false, 'Ruled out because a missed miscarriage shows a non-viable pregnancy on scan, whereas here a fetal heartbeat is present.', 3),
('cd000000-0000-0000-0000-000000000008', 'D', 'Complete miscarriage', false, 'Ruled out because complete miscarriage shows an empty uterus with no ongoing pregnancy, not a viable intrauterine pregnancy.', 4),
('cd000000-0000-0000-0000-000000000008', 'E', 'Septic miscarriage', false, 'Ruled out because there are no signs of infection (fever, offensive discharge) described in this presentation.', 5),
('cd000000-0000-0000-0000-000000000009', 'A', 'Immediate surgical evacuation is mandatory in all cases of missed miscarriage', false, 'Ruled out because surgical evacuation is one of three options (expectant, medical, surgical); it is not mandatory when the woman is stable and asymptomatic.', 1),
('cd000000-0000-0000-0000-000000000009', 'B', 'Expectant management, with a repeat urine pregnancy test after 3 weeks to confirm completion', true, 'Correct. Expectant management is a valid option for missed miscarriage alongside medical and surgical management, and a negative urine pregnancy test at 3 weeks helps confirm completion.', 2),
('cd000000-0000-0000-0000-000000000009', 'C', 'Antibiotics are required before any management option can be offered', false, 'Ruled out because antibiotics are only indicated if there are signs of infection, which are absent here.', 3),
('cd000000-0000-0000-0000-000000000009', 'D', 'Anti-D immunoglobulin is never required regardless of gestation or management approach', false, 'Ruled out because anti-D immunoglobulin should be considered for Rhesus-negative women, particularly with surgical management.', 4),
('cd000000-0000-0000-0000-000000000009', 'E', 'Methotrexate is first-line treatment for missed miscarriage', false, 'Ruled out because methotrexate is used for medical management of ectopic pregnancy, not for miscarriage.', 5),
('cd000000-0000-0000-0000-000000000010', 'A', 'Reassure that nausea is normal in pregnancy and advise ginger tea only', false, 'Ruled out because this significantly underestimates the severity; significant weight loss and ketonuria indicate hyperemesis gravidarum requiring active treatment.', 1),
('cd000000-0000-0000-0000-000000000010', 'B', 'Start oral antiemetics only and discharge home', false, 'Ruled out because she is unable to tolerate oral fluids, so oral treatment alone is inadequate; IV treatment is needed.', 2),
('cd000000-0000-0000-0000-000000000010', 'C', 'Advise termination of pregnancy due to the severity of symptoms', false, 'Ruled out because hyperemesis gravidarum is a treatable condition and does not itself necessitate termination.', 3),
('cd000000-0000-0000-0000-000000000010', 'D', 'Admit for IV fluid rehydration and antiemetics (e.g. cyclizine or ondansetron)', true, 'Correct. Significant weight loss, dehydration and ketonuria in the context of intractable vomiting define hyperemesis gravidarum, requiring admission for IV rehydration and antiemetic treatment.', 4),
('cd000000-0000-0000-0000-000000000010', 'E', 'Arrange outpatient dietician referral only, with no medication', false, 'Ruled out because this does not address the acute dehydration and ketonuria requiring admission and IV treatment.', 5),
('cd000000-0000-0000-0000-000000000011', 'A', 'Expectant management, as the pregnancy will resolve spontaneously', false, 'Ruled out because molar pregnancy requires evacuation and specialist follow-up, not expectant management.', 1),
('cd000000-0000-0000-0000-000000000011', 'B', 'Referral to a specialist regional trophoblastic disease centre for surgical evacuation and follow-up', true, 'Correct. This presentation is consistent with a molar pregnancy; management is surgical evacuation followed by registration with a specialist centre for serial hCG monitoring given the risk of persistent or malignant trophoblastic disease.', 2),
('cd000000-0000-0000-0000-000000000011', 'C', 'Reassure that this is a normal twin pregnancy given the high hCG', false, 'Ruled out because the ultrasound and clinical findings are characteristic of molar pregnancy, not a twin pregnancy.', 3),
('cd000000-0000-0000-0000-000000000011', 'D', 'Start methotrexate immediately without evacuation', false, 'Ruled out because evacuation is the first step; methotrexate is reserved for cases progressing to malignant gestational trophoblastic disease.', 4),
('cd000000-0000-0000-0000-000000000011', 'E', 'Advise attempting conception again immediately after this pregnancy ends', false, 'Ruled out because effective contraception is advised for a period of hCG follow-up (typically 6-12 months), as a new pregnancy would confound monitoring.', 5),
('cd000000-0000-0000-0000-000000000012', 'A', 'Repeat serum beta-hCG in 48 hours to assess the trend', true, 'Correct. In a stable woman with a pregnancy of unknown location, serial beta-hCG measurement 48 hours apart is the standard approach to guide further management.', 1),
('cd000000-0000-0000-0000-000000000012', 'B', 'Immediate laparoscopy to exclude ectopic pregnancy', false, 'Ruled out because surgery is not indicated in a stable, asymptomatic patient without evidence of ectopic pregnancy on scan.', 2),
('cd000000-0000-0000-0000-000000000012', 'C', 'Administer methotrexate empirically without further investigation', false, 'Ruled out because methotrexate should not be given without a confirmed diagnosis of ectopic pregnancy.', 3),
('cd000000-0000-0000-0000-000000000012', 'D', 'Discharge with no follow-up required, as the scan was normal', false, 'Ruled out because a pregnancy of unknown location requires follow-up until the outcome is clarified, given the risk of an undiagnosed ectopic pregnancy.', 4),
('cd000000-0000-0000-0000-000000000012', 'E', 'Advise that this confirms a very early miscarriage and no follow-up is needed', false, 'Ruled out because this cannot be concluded without observing the beta-hCG trend over time.', 5),
('cd000000-0000-0000-0000-000000000013', 'A', 'Reassure that postmenopausal bleeding is usually benign and review in six months', false, 'Ruled out because postmenopausal bleeding always requires urgent assessment to exclude malignancy, not deferred review.', 1),
('cd000000-0000-0000-0000-000000000013', 'B', 'Start topical vaginal oestrogen and reassess in three months', false, 'Ruled out because treatment should not be started before malignancy has been excluded.', 2),
('cd000000-0000-0000-0000-000000000013', 'C', 'Arrange a routine (non-urgent) gynaecology outpatient referral', false, 'Ruled out because postmenopausal bleeding warrants the urgent 2-week-wait pathway, not a routine referral.', 3),
('cd000000-0000-0000-0000-000000000013', 'D', 'Reassure that her obesity and diabetes are unrelated to her bleeding', false, 'Ruled out because both obesity and diabetes are recognised risk factors for endometrial cancer, not unrelated findings.', 4),
('cd000000-0000-0000-0000-000000000013', 'E', 'Urgent (2-week wait) referral for transvaginal ultrasound to assess endometrial thickness', true, 'Correct. Postmenopausal bleeding is a red-flag symptom requiring urgent investigation to exclude endometrial cancer; obesity and diabetes are additional risk factors here.', 5),
('cd000000-0000-0000-0000-000000000014', 'A', 'Reassure that CA125 elevation is nonspecific and no further action is needed', false, 'Ruled out because this level of elevation combined with a complex mass and suggestive symptoms is highly concerning and requires urgent action, not reassurance.', 1),
('cd000000-0000-0000-0000-000000000014', 'B', 'Arrange a repeat CA125 in six months before any referral', false, 'Ruled out because this delay is unsafe given the strong suspicion of malignancy.', 2),
('cd000000-0000-0000-0000-000000000014', 'C', 'Calculate the Risk of Malignancy Index and refer urgently to a gynaecological oncology multidisciplinary team', true, 'Correct. Persistent bloating, a complex adnexal mass and markedly elevated CA125 in a postmenopausal woman are highly suspicious for ovarian cancer; the Risk of Malignancy Index guides urgent specialist referral.', 3),
('cd000000-0000-0000-0000-000000000014', 'D', 'Refer for laparoscopic ovarian cystectomy in a general gynaecology clinic', false, 'Ruled out because suspected malignancy requires assessment by a specialist gynaecological oncology multidisciplinary team, not routine cystectomy.', 4),
('cd000000-0000-0000-0000-000000000014', 'E', 'Start empirical antibiotics for suspected pelvic infection', false, 'Ruled out because the clinical picture (bloating, early satiety, complex mass, elevated CA125) is not consistent with infection.', 5),
('cd000000-0000-0000-0000-000000000015', 'A', 'Repeat cervical screening test in 3 years as per the routine interval', false, 'Ruled out because an abnormal result requires colposcopy referral, not a return to the routine screening interval.', 1),
('cd000000-0000-0000-0000-000000000015', 'B', 'Reassure and repeat screening in 12 months, as HPV infections usually clear spontaneously', false, 'Ruled out because high-grade dyskaryosis requires urgent colposcopy, not a delayed repeat test.', 2),
('cd000000-0000-0000-0000-000000000015', 'C', 'Arrange HPV vaccination to treat the current infection', false, 'Ruled out because HPV vaccination is prophylactic and has no role in treating an established infection.', 3),
('cd000000-0000-0000-0000-000000000015', 'D', 'Referral to colposcopy for further assessment', true, 'Correct. High-grade dyskaryosis on cytology requires prompt colposcopic assessment and biopsy.', 4),
('cd000000-0000-0000-0000-000000000015', 'E', 'Perform a hysterectomy as first-line management', false, 'Ruled out because this is grossly excessive before colposcopy and biopsy have characterised the abnormality.', 5),
('cd000000-0000-0000-0000-000000000016', 'A', 'Continue topical steroids for a further 3 months before reassessment', false, 'Ruled out because the lesion has already failed to respond to treatment and is persistent, so it needs urgent biopsy rather than further empirical therapy.', 1),
('cd000000-0000-0000-0000-000000000016', 'B', 'Reassure that lichen sclerosus itself explains the lump and no further action is needed', false, 'Ruled out because lichen sclerosus is a risk factor for vulval cancer, not a reassuring explanation to dismiss a new persistent lesion.', 2),
('cd000000-0000-0000-0000-000000000016', 'C', 'Prescribe topical antifungal treatment for presumed candidiasis', false, 'Ruled out because this is inconsistent with a persistent ulcerated lump unresponsive to steroids.', 3),
('cd000000-0000-0000-0000-000000000016', 'D', 'Arrange a routine (non-urgent) referral in 12 weeks', false, 'Ruled out because red-flag features require urgent referral, not a routine, delayed pathway.', 4),
('cd000000-0000-0000-0000-000000000016', 'E', 'Urgent (2-week wait) referral to gynaecology for biopsy to exclude vulval cancer', true, 'Correct. A persistent, non-healing ulcerated vulval lump in an older woman with lichen sclerosus is a red-flag feature requiring urgent biopsy to exclude vulval cancer.', 5),
('cd000000-0000-0000-0000-000000000017', 'A', 'Reassure and arrange a repeat ultrasound in 12 months', false, 'Ruled out because complex features in a postmenopausal woman are concerning and should not be left for a year without specialist input.', 1),
('cd000000-0000-0000-0000-000000000017', 'B', 'Manage conservatively as simple ovarian cysts in postmenopausal women usually resolve', false, 'Ruled out because this cyst is complex, not simple, so the conservative pathway for simple cysts does not apply.', 2),
('cd000000-0000-0000-0000-000000000017', 'C', 'Calculate the Risk of Malignancy Index and refer to a gynaecological oncology specialist', true, 'Correct. Complex morphology (septations, papillary projections) in a postmenopausal woman, combined with an elevated CA125, warrants risk stratification and specialist referral even though the CA125 rise is only mild.', 3),
('cd000000-0000-0000-0000-000000000017', 'D', 'Start the combined oral contraceptive pill to shrink the cyst', false, 'Ruled out because hormonal contraception is not an effective treatment for an existing ovarian cyst and is not the appropriate management here.', 4),
('cd000000-0000-0000-0000-000000000017', 'E', 'Discharge with no follow-up, as CA125 is only mildly elevated', false, 'Ruled out because the complex morphology alone is concerning regardless of only a mild CA125 rise, and specialist assessment is required.', 5),
('cd000000-0000-0000-0000-000000000018', 'A', 'Reassure that vaginal bleeding is a known side effect of tamoxifen and no investigation is needed', false, $x$Ruled out because tamoxifen's endometrial effects are exactly why any postmenopausal bleeding on this drug must be investigated urgently, not dismissed.$x$, 1),
('cd000000-0000-0000-0000-000000000018', 'B', 'Stop tamoxifen immediately without gynaecological assessment', false, 'Ruled out because decisions about tamoxifen should involve the oncology team, and this does not substitute for the urgent need to investigate the bleeding itself.', 2),
('cd000000-0000-0000-0000-000000000018', 'C', 'Arrange a routine gynaecology referral in 12 weeks', false, 'Ruled out because postmenopausal bleeding requires urgent referral, not a routine, delayed pathway.', 3),
('cd000000-0000-0000-0000-000000000018', 'D', 'Urgent referral for transvaginal ultrasound and consideration of endometrial biopsy', true, 'Correct. Tamoxifen has an oestrogenic effect on the endometrium and increases the risk of endometrial hyperplasia and cancer; any postmenopausal bleeding in a woman taking tamoxifen requires urgent investigation.', 4),
('cd000000-0000-0000-0000-000000000018', 'E', 'Prescribe hormone replacement therapy to manage her symptoms', false, 'Ruled out because this is inappropriate and unrelated to the need to investigate the presenting bleeding.', 5),
('cd000000-0000-0000-0000-000000000019', 'A', 'Attempt to push the cord back into the uterus before further assessment', false, 'Ruled out because the cord should never be pushed back into the uterus, as this increases infection and vasospasm risk; the presenting part should be elevated instead.', 1),
('cd000000-0000-0000-0000-000000000019', 'B', 'Manually elevate the presenting part to relieve cord compression, and prepare for immediate category 1 caesarean section', true, 'Correct. Cord prolapse is an obstetric emergency; immediate management is to elevate the presenting part off the cord to relieve compression while expediting delivery, usually by category 1 caesarean section.', 2),
('cd000000-0000-0000-0000-000000000019', 'C', 'Perform artificial rupture of membranes to expedite delivery', false, 'Ruled out because membranes have already ruptured; this action is irrelevant to managing the emergency.', 3),
('cd000000-0000-0000-0000-000000000019', 'D', 'Commence an oxytocin infusion to accelerate labour progress', false, 'Ruled out because this delays the emergency delivery required and does not address cord compression.', 4),
('cd000000-0000-0000-0000-000000000019', 'E', 'Reassure and continue routine labour monitoring', false, 'Ruled out because this is an obstetric emergency requiring immediate action, not routine monitoring.', 5),
('cd000000-0000-0000-0000-000000000020', 'A', 'McRoberts manoeuvre (hyperflexion and abduction of the maternal hips)', true, 'Correct. McRoberts manoeuvre is the first-line manoeuvre for shoulder dystocia, increasing the functional diameter of the pelvis.', 1),
('cd000000-0000-0000-0000-000000000020', 'B', 'Fundal pressure applied firmly to assist delivery', false, 'Ruled out because fundal pressure is contraindicated in shoulder dystocia due to increased risk of uterine rupture and worsening impaction.', 2),
('cd000000-0000-0000-0000-000000000020', 'C', 'Immediate caesarean section', false, 'Ruled out because caesarean section is not feasible once the head has already delivered; vaginal manoeuvres are the first-line approach.', 3),
('cd000000-0000-0000-0000-000000000020', 'D', 'Continued strong downward traction on the fetal head', false, 'Ruled out because excessive traction risks brachial plexus injury and is contraindicated.', 4),
('cd000000-0000-0000-0000-000000000020', 'E', 'Fundal pressure combined with strong traction on the head', false, 'Ruled out because both actions are contraindicated in shoulder dystocia and worsen outcomes.', 5),
('cd000000-0000-0000-0000-000000000021', 'A', 'Continue routine monitoring, as the baseline rate is within normal limits', false, 'Ruled out because this ignores the pathological deceleration pattern and reduced variability, which are the concerning features here.', 1),
('cd000000-0000-0000-0000-000000000021', 'B', 'Increase the oxytocin infusion to accelerate labour', false, 'Ruled out because oxytocin can worsen fetal hypoxia in the context of a pathological CTG; it should be stopped or reduced, not increased.', 2),
('cd000000-0000-0000-0000-000000000021', 'C', 'Perform fetal blood sampling, or expedite delivery if this is not feasible, due to a pathological CTG', true, 'Correct. Recurrent late decelerations with reduced variability constitute a pathological CTG, suggesting possible fetal hypoxia, and warrant escalation with fetal blood sampling or expedited delivery.', 3),
('cd000000-0000-0000-0000-000000000021', 'D', 'Reassure the mother that decelerations are a normal feature of labour and no action is needed', false, 'Ruled out because recurrent late decelerations are a concerning, pathological finding requiring action.', 4),
('cd000000-0000-0000-0000-000000000021', 'E', 'Discharge home to await spontaneous delivery', false, 'Ruled out because she is already in established labour with a pathological CTG, an emergency situation requiring in-hospital escalation.', 5),
('cd000000-0000-0000-0000-000000000022', 'A', 'Proceed immediately to caesarean section without further intervention', false, 'Ruled out because this is premature before trying augmentation measures, which may resolve the delay.', 1),
('cd000000-0000-0000-0000-000000000022', 'B', 'Perform amniotomy (artificial rupture of membranes) and consider oxytocin augmentation', true, 'Correct. This represents delay in the first stage of labour; amniotomy and, if needed, oxytocin augmentation are the appropriate first steps when membranes are intact or contractions are inadequate.', 2),
('cd000000-0000-0000-0000-000000000022', 'C', 'Reassure and continue expectant monitoring for a further 8 hours without intervention', false, 'Ruled out because this delay is unacceptable given the documented slow progress; action should be taken now.', 3),
('cd000000-0000-0000-0000-000000000022', 'D', 'Discontinue all monitoring and allow ambulation only', false, 'Ruled out because this is insufficient for confirmed slow progress that needs active augmentation.', 4),
('cd000000-0000-0000-0000-000000000022', 'E', 'Administer magnesium sulfate to relax the uterus', false, 'Ruled out because magnesium sulfate is used for seizure prophylaxis in pre-eclampsia or tocolysis in preterm labour, not for augmenting labour progress.', 5),
('cd000000-0000-0000-0000-000000000023', 'A', 'Placenta praevia', false, 'Ruled out because placenta praevia typically causes painless bleeding without uterine tenderness, unlike this presentation.', 1),
('cd000000-0000-0000-0000-000000000023', 'B', 'Vasa praevia', false, 'Ruled out because vasa praevia presents with painless bleeding at rupture of membranes accompanied by fetal distress, not a woody-hard tender uterus.', 2),
('cd000000-0000-0000-0000-000000000023', 'C', 'Uterine rupture', false, 'Ruled out because there is no mention of a previous uterine scar or labour, making this less consistent than abruption in this scenario.', 3),
('cd000000-0000-0000-0000-000000000023', 'D', 'Round ligament pain', false, 'Ruled out because this is a benign musculoskeletal cause not associated with bleeding or a woody-hard uterus.', 4),
('cd000000-0000-0000-0000-000000000023', 'E', 'Placental abruption', true, $x$Correct. Painful bleeding with a tender, 'woody-hard' uterus and risk factors (smoking, hypertension) are classic for placental abruption.$x$, 5),
('cd000000-0000-0000-0000-000000000024', 'A', 'Normal progression of established labour', false, 'Ruled out because this presentation is clearly abnormal, with sudden pain, loss of contractions, and haemodynamic compromise.', 1),
('cd000000-0000-0000-0000-000000000024', 'B', 'Placenta praevia', false, 'Ruled out because this does not fit the sudden cessation of contractions and scar-related presentation; placenta praevia typically causes painless bleeding.', 2),
('cd000000-0000-0000-0000-000000000024', 'C', 'Chorioamnionitis', false, 'Ruled out because this would present with fever and signs of infection, not sudden pain and fetal bradycardia.', 3),
('cd000000-0000-0000-0000-000000000024', 'D', 'Uterine rupture', true, 'Correct. Sudden severe pain, cessation of contractions, and fetal bradycardia with maternal shock in a woman attempting VBAC is the classic presentation of uterine rupture at the previous scar.', 4),
('cd000000-0000-0000-0000-000000000024', 'E', 'Braxton Hicks contractions', false, 'Ruled out because these are benign and not associated with haemodynamic compromise or fetal bradycardia.', 5),
('cd000000-0000-0000-0000-000000000025', 'A', 'Levonorgestrel-releasing intrauterine system (LNG-IUS)', true, 'Correct. NICE recommends the LNG-IUS as first-line treatment for heavy menstrual bleeding when there is no identified structural or histological abnormality.', 1),
('cd000000-0000-0000-0000-000000000025', 'B', 'Endometrial ablation', false, 'Ruled out because surgical options are considered after medical treatment has failed or been declined, not as first-line.', 2),
('cd000000-0000-0000-0000-000000000025', 'C', 'Hysterectomy', false, 'Ruled out because hysterectomy is reserved for cases where other treatments have failed or are declined, not as first-line management.', 3),
('cd000000-0000-0000-0000-000000000025', 'D', 'Combined oral contraceptive pill as the sole first-choice option', false, 'Ruled out because the LNG-IUS is preferred first-line over the combined pill in current guidance.', 4),
('cd000000-0000-0000-0000-000000000025', 'E', 'Tranexamic acid combined with NSAIDs only, with no hormonal option offered', false, 'Ruled out because non-hormonal treatments are alternatives, but the LNG-IUS is the preferred first-line option when acceptable to the patient.', 5),
('cd000000-0000-0000-0000-000000000026', 'A', 'Uterine fibroids (leiomyomas)', true, 'Correct. Heavy menstrual bleeding, pelvic pressure, and a palpable pelvic mass with intramural fibroids confirmed on ultrasound are classic for uterine fibroids.', 1),
('cd000000-0000-0000-0000-000000000026', 'B', 'Endometrial polyp', false, 'Ruled out because polyps are typically small and cause intermenstrual bleeding rather than a large palpable pelvic mass.', 2),
('cd000000-0000-0000-0000-000000000026', 'C', 'Ovarian cyst', false, 'Ruled out because ultrasound specifically demonstrates intramural fibroids arising from the uterus, not an ovarian mass.', 3),
('cd000000-0000-0000-0000-000000000026', 'D', 'Adenomyosis', false, 'Ruled out because adenomyosis typically causes diffuse uterine enlargement and tenderness without discrete masses, unlike the discrete fibroids seen here.', 4),
('cd000000-0000-0000-0000-000000000026', 'E', 'Endometrial cancer', false, 'Ruled out because this would show an endometrial abnormality rather than discrete intramural masses, and is a less likely diagnosis given the ultrasound findings.', 5),
('cd000000-0000-0000-0000-000000000027', 'A', 'Transvaginal ultrasound alone is sufficient to confirm the diagnosis', false, 'Ruled out because ultrasound can be normal in endometriosis and is not always diagnostic.', 1),
('cd000000-0000-0000-0000-000000000027', 'B', 'Serum CA125 level', false, 'Ruled out because CA125 is nonspecific and not diagnostic of endometriosis.', 2),
('cd000000-0000-0000-0000-000000000027', 'C', 'Endometrial biopsy', false, 'Ruled out because this assesses pathology within the uterine cavity, not extrauterine endometriosis.', 3),
('cd000000-0000-0000-0000-000000000027', 'D', 'MRI pelvis alone, with laparoscopy never required', false, 'Ruled out because MRI can help characterise deep disease, but laparoscopy with biopsy remains the gold standard for definitive diagnosis.', 4),
('cd000000-0000-0000-0000-000000000027', 'E', 'Diagnostic laparoscopy', true, 'Correct. Diagnostic laparoscopy with visualisation (and biopsy) of endometriotic lesions is the gold-standard investigation, as ultrasound can be normal even with significant disease.', 5),
('cd000000-0000-0000-0000-000000000028', 'A', 'Premature ovarian insufficiency', false, 'Ruled out because this would show low oestrogen with high FSH and amenorrhoea, not hirsutism with this ultrasound picture.', 1),
('cd000000-0000-0000-0000-000000000028', 'B', 'Congenital adrenal hyperplasia', false, 'Ruled out because this typically presents earlier in life with more severe virilisation, making it a less likely new presentation at this age with this clinical picture.', 2),
('cd000000-0000-0000-0000-000000000028', 'C', 'Polycystic ovary syndrome', true, 'Correct. This meets the Rotterdam criteria (oligomenorrhoea, clinical hyperandrogenism/hirsutism, and polycystic ovaries on ultrasound), with other causes of irregular periods and hirsutism excluded.', 3),
('cd000000-0000-0000-0000-000000000028', 'D', 'Hyperprolactinaemia', false, 'Ruled out because prolactin is normal, excluding this diagnosis.', 4),
('cd000000-0000-0000-0000-000000000028', 'E', 'Hypothyroidism', false, 'Ruled out because TSH is normal, excluding this diagnosis.', 5),
('cd000000-0000-0000-0000-000000000029', 'A', 'Refer urgently to gynaecological oncology', false, 'Ruled out because this is not indicated for a simple, small cyst with entirely benign features.', 1),
('cd000000-0000-0000-0000-000000000029', 'B', 'Arrange immediate surgical removal of the cyst', false, 'Ruled out because surgery is unnecessary for a small, simple, asymptomatic cyst.', 2),
('cd000000-0000-0000-0000-000000000029', 'C', 'Start the combined oral contraceptive pill specifically to shrink the cyst', false, 'Ruled out because this is not proven to hasten resolution of an existing cyst and is not the recommended management here.', 3),
('cd000000-0000-0000-0000-000000000029', 'D', 'Reassure and manage conservatively, as simple cysts under 5cm in premenopausal women are usually physiological and often resolve spontaneously', true, 'Correct. Simple, unilocular, thin-walled ovarian cysts under 5cm in premenopausal women are usually functional and can be managed conservatively with follow-up.', 4),
('cd000000-0000-0000-0000-000000000029', 'E', 'Request CA125 and refer urgently regardless of findings', false, 'Ruled out because this is not indicated given the benign appearance and low risk in a young premenopausal woman.', 5),
('cd000000-0000-0000-0000-000000000030', 'A', 'Uterine fibroids', false, 'Ruled out because fibroids would show discrete masses, not the diffuse globular change seen here without discrete lesions.', 1),
('cd000000-0000-0000-0000-000000000030', 'B', 'Adenomyosis', true, $x$Correct. A diffusely enlarged, tender, 'boggy' uterus with dysmenorrhoea and menorrhagia, together with a globular uterus and indistinct endometrial-myometrial junction on ultrasound, is characteristic of adenomyosis.$x$, 2),
('cd000000-0000-0000-0000-000000000030', 'C', 'Endometrial polyp', false, 'Ruled out because a polyp is a localised lesion and does not explain diffuse uterine enlargement.', 3),
('cd000000-0000-0000-0000-000000000030', 'D', 'Pelvic inflammatory disease', false, 'Ruled out because this would present with signs of infection and cervical discharge, a different clinical picture from chronic dysmenorrhoea and menorrhagia.', 4),
('cd000000-0000-0000-0000-000000000030', 'E', 'Endometrial cancer', false, 'Ruled out because this would show a focal endometrial abnormality rather than diffuse myometrial changes.', 5),
('cd000000-0000-0000-0000-000000000031', 'A', 'Await chlamydia and gonorrhoea swab results before starting any treatment', false, 'Ruled out because this delay is inappropriate given the risk of tubal damage and long-term sequelae from untreated PID.', 1),
('cd000000-0000-0000-0000-000000000031', 'B', 'Reassure and provide analgesia only, with no antibiotics', false, 'Ruled out because antibiotic treatment is required for PID, and analgesia alone is inadequate.', 2),
('cd000000-0000-0000-0000-000000000031', 'C', 'Arrange laparoscopy as the first-line investigation before treatment', false, 'Ruled out because laparoscopy is not first-line; it is reserved for uncertain diagnosis or failure to respond to treatment.', 3),
('cd000000-0000-0000-0000-000000000031', 'D', 'Treat only for a urinary tract infection with trimethoprim', false, 'Ruled out because this does not fit the clinical picture of cervical excitation, adnexal tenderness, and discharge, which are characteristic of PID.', 4),
('cd000000-0000-0000-0000-000000000031', 'E', 'Start empirical antibiotics for pelvic inflammatory disease (e.g. IM ceftriaxone plus oral doxycycline and metronidazole) without waiting for swab results', true, 'Correct. Pelvic inflammatory disease is a clinical diagnosis, and prompt empirical antibiotic treatment reduces the risk of long-term complications such as tubal infertility and chronic pelvic pain.', 5),
('cd000000-0000-0000-0000-000000000032', 'A', 'Analgesia and observation, with reassessment in 24 hours', false, 'Ruled out because this unsafe delay risks irreversible ovarian ischaemia and necrosis.', 1),
('cd000000-0000-0000-0000-000000000032', 'B', 'Start broad-spectrum antibiotics for presumed pelvic infection', false, 'Ruled out because this does not address the underlying torsion and reflects an incorrect diagnostic assumption.', 2),
('cd000000-0000-0000-0000-000000000032', 'C', 'Urgent laparoscopy for ovarian detorsion, with cystectomy if appropriate', true, 'Correct. Ovarian torsion is a surgical emergency requiring prompt detorsion to salvage the ovary before irreversible ischaemia occurs.', 3),
('cd000000-0000-0000-0000-000000000032', 'D', 'Arrange an outpatient gynaecology appointment in 2 weeks', false, 'Ruled out because this is dangerously delayed given the emergency nature of the presentation.', 4),
('cd000000-0000-0000-0000-000000000032', 'E', 'Administer emergency contraception given her pain', false, 'Ruled out because this is irrelevant to the clinical presentation of suspected ovarian torsion.', 5),
('cd000000-0000-0000-0000-000000000033', 'A', 'Vulval cancer', false, 'Ruled out because vulval cancer would present as a non-healing lump or ulcer over a longer time course, not an acutely painful fluctuant abscess.', 1),
('cd000000-0000-0000-0000-000000000033', 'B', 'Genital herpes', false, 'Ruled out because this typically presents with multiple painful vesicles or ulcers, not a single fluctuant swelling.', 2),
('cd000000-0000-0000-0000-000000000033', 'C', 'Sebaceous cyst', false, $x$Ruled out because sebaceous cysts are usually less acutely painful and are not classically located at the Bartholin's gland site with fluctuance.$x$, 3),
('cd000000-0000-0000-0000-000000000033', 'D', $x$Bartholin's abscess$x$, true, $x$Correct. A tender, fluctuant swelling at the posterior introitus is the classic location and presentation of a Bartholin's abscess.$x$, 4),
('cd000000-0000-0000-0000-000000000033', 'E', 'Lichen sclerosus', false, 'Ruled out because this presents with itching and skin changes such as whitening and atrophy, not an acute fluctuant abscess.', 5),
('cd000000-0000-0000-0000-000000000034', 'A', 'Remove the tampon immediately, and commence IV fluid resuscitation and IV antibiotics', true, 'Correct. This presentation is consistent with toxic shock syndrome; immediate management includes removing the source (tampon) and providing IV fluid resuscitation with broad-spectrum antibiotics.', 1),
('cd000000-0000-0000-0000-000000000034', 'B', 'Reassure and advise she can continue using tampons throughout menstruation', false, 'Ruled out because this is dangerously wrong given the diagnosis of toxic shock syndrome, which requires immediate removal of the tampon.', 2),
('cd000000-0000-0000-0000-000000000034', 'C', 'Prescribe oral antibiotics only and discharge home', false, 'Ruled out because this is inadequate given hypotension and shock; she requires admission and IV treatment.', 3),
('cd000000-0000-0000-0000-000000000034', 'D', 'Arrange outpatient blood cultures and review results in 48 hours before starting treatment', false, 'Ruled out because this delays urgent treatment in a shocked patient with a life-threatening condition.', 4),
('cd000000-0000-0000-0000-000000000034', 'E', 'Administer antiemetics only, treating this as gastroenteritis', false, 'Ruled out because this approach misses the life-threatening diagnosis of toxic shock syndrome.', 5),
('cd000000-0000-0000-0000-000000000035', 'A', 'Emergency laparotomy is required in all cases of ruptured ovarian cyst', false, 'Ruled out because surgery is not needed when the patient is stable; this would represent over-treatment.', 1),
('cd000000-0000-0000-0000-000000000035', 'B', 'Conservative management with analgesia and observation, as she is haemodynamically stable', true, 'Correct. A ruptured functional ovarian cyst causing minor haemoperitoneum in a haemodynamically stable woman can usually be managed conservatively.', 2),
('cd000000-0000-0000-0000-000000000035', 'C', 'Start empirical antibiotics for presumed pelvic infection', false, 'Ruled out because the clinical and ultrasound picture is consistent with cyst rupture, not infection.', 3),
('cd000000-0000-0000-0000-000000000035', 'D', 'Arrange emergency blood transfusion regardless of haemoglobin level', false, 'Ruled out because transfusion is unnecessary without evidence of significant haemorrhage or anaemia.', 4),
('cd000000-0000-0000-0000-000000000035', 'E', 'Discharge with no follow-up or safety-netting advice', false, 'Ruled out because safety-netting on warning signs (worsening pain, dizziness) is still appropriate even when conservative management is chosen.', 5),
('cd000000-0000-0000-0000-000000000036', 'A', 'Discharge home to continue the same oral antibiotics as before', false, 'Ruled out because this is inadequate given the lack of improvement and formation of a tubo-ovarian abscess, which requires escalation of care.', 1),
('cd000000-0000-0000-0000-000000000036', 'B', 'Immediate hysterectomy and bilateral salpingo-oophorectomy', false, 'Ruled out because this is an excessive first-line treatment; conservative IV antibiotics with or without drainage are tried first.', 2),
('cd000000-0000-0000-0000-000000000036', 'C', 'Admission for IV broad-spectrum antibiotics, with consideration of drainage or surgical intervention if there is no clinical improvement', true, 'Correct. Failure to improve on oral antibiotics with evidence of a tubo-ovarian abscess requires admission for IV antibiotics, escalating to drainage or surgery if there is no response.', 3),
('cd000000-0000-0000-0000-000000000036', 'D', 'Reassure that this will resolve without any change in treatment', false, 'Ruled out because this is unsafe given ongoing fever and abscess formation, which require escalation of treatment.', 4),
('cd000000-0000-0000-0000-000000000036', 'E', 'Arrange outpatient review in 1 week with no change in management', false, 'Ruled out because this is an unsafe delay given ongoing fever and an untreated abscess, which risks rupture and sepsis.', 5),
('cd000000-0000-0000-0000-000000000037', 'A', 'Retained placental tissue', false, 'Ruled out because the placenta has already been delivered, and the soft boggy uterus is most consistent with atony rather than retained tissue at this stage.', 1),
('cd000000-0000-0000-0000-000000000037', 'B', 'Genital tract trauma (perineal or cervical tear)', false, 'Ruled out because trauma typically presents with a well-contracted uterus and a visible laceration, not a boggy uterus.', 2),
('cd000000-0000-0000-0000-000000000037', 'C', 'Uterine inversion', false, 'Ruled out because this would present with a mass at the introitus or an absent fundus on abdominal palpation, not simply a boggy uterus.', 3),
('cd000000-0000-0000-0000-000000000037', 'D', 'Uterine atony', true, $x$Correct. Uterine atony is the most common cause of primary postpartum haemorrhage, and the soft, poorly contracted ('boggy') uterus described is classic for this cause.$x$, 4),
('cd000000-0000-0000-0000-000000000037', 'E', 'Coagulopathy from an undiagnosed clotting disorder', false, 'Ruled out because this is a less common cause, and the boggy uterus specifically points to atony as the most likely cause.', 5),
('cd000000-0000-0000-0000-000000000038', 'A', 'Reassurance and discharge, as bleeding after delivery is expected up to six weeks', false, 'Ruled out because this dismisses the concerning fever, uterine tenderness, and confirmed retained tissue, which require active treatment.', 1),
('cd000000-0000-0000-0000-000000000038', 'B', 'Oral misoprostol alone with no antibiotics, regardless of fever', false, 'Ruled out because the fever suggests infection requiring antibiotics, and evacuation is still likely needed given the ultrasound findings.', 2),
('cd000000-0000-0000-0000-000000000038', 'C', 'Arrange outpatient review in 2 weeks', false, 'Ruled out because this is an unsafe delay given active bleeding, fever, and retained tissue.', 3),
('cd000000-0000-0000-0000-000000000038', 'D', 'Perform hysterectomy as first-line treatment', false, 'Ruled out because this is excessive; surgical evacuation of retained products is the appropriate first-line surgical management.', 4),
('cd000000-0000-0000-0000-000000000038', 'E', 'IV antibiotics and surgical evacuation of retained products of conception', true, 'Correct. Secondary postpartum haemorrhage with fever, uterine tenderness, and confirmed retained products requires both antibiotics for likely infection and surgical evacuation.', 5),
('cd000000-0000-0000-0000-000000000039', 'A', 'Postpartum endometritis', true, 'Correct. Fever, uterine tenderness, and offensive-smelling lochia after delivery, particularly following caesarean section, are classic for postpartum endometritis.', 1),
('cd000000-0000-0000-0000-000000000039', 'B', 'Wound infection', false, 'Ruled out because there is no wound erythema or discharge described, making this less likely than endometritis.', 2),
('cd000000-0000-0000-0000-000000000039', 'C', 'Mastitis', false, 'Ruled out because mastitis presents with breast symptoms, not uterine tenderness and offensive lochia.', 3),
('cd000000-0000-0000-0000-000000000039', 'D', 'Urinary tract infection', false, 'Ruled out because this would present with urinary symptoms rather than uterine tenderness and offensive lochia.', 4),
('cd000000-0000-0000-0000-000000000039', 'E', 'Normal postpartum recovery', false, 'Ruled out because fever, a tender uterus, and offensive lochia are abnormal findings, not features of normal recovery.', 5),
('cd000000-0000-0000-0000-000000000040', 'A', 'Second-degree tear', false, 'Ruled out because second-degree tears involve the perineal muscles only, without any anal sphincter involvement.', 1),
('cd000000-0000-0000-0000-000000000040', 'B', 'Third-degree tear, grade 3a', true, 'Correct. Third-degree tears involve the anal sphincter complex; grade 3a specifically describes less than 50% of the external anal sphincter thickness torn, matching this description.', 2),
('cd000000-0000-0000-0000-000000000040', 'C', 'Fourth-degree tear', false, 'Ruled out because fourth-degree tears also involve the rectal mucosa, which is intact in this case.', 3),
('cd000000-0000-0000-0000-000000000040', 'D', 'First-degree tear', false, 'Ruled out because first-degree tears are superficial, involving skin only.', 4),
('cd000000-0000-0000-0000-000000000040', 'E', 'Third-degree tear, grade 3c', false, 'Ruled out because grade 3c involves both the external and internal anal sphincter torn, whereas here the internal sphincter is intact.', 5),
('cd000000-0000-0000-0000-000000000041', 'A', 'Urgent psychiatric assessment and consideration of admission to a specialist mother and baby unit', true, 'Correct. Rapid onset confusion with delusional beliefs in the early postpartum period indicates puerperal psychosis, a psychiatric emergency requiring urgent assessment and likely admission to a mother and baby unit.', 1),
('cd000000-0000-0000-0000-000000000041', 'B', $x$Reassure that this represents normal 'baby blues' and will resolve within a few days without intervention$x$, false, 'Ruled out because baby blues involves mild mood lability without psychotic symptoms; delusions and confusion indicate a more serious condition requiring urgent assessment.', 2),
('cd000000-0000-0000-0000-000000000041', 'C', 'Prescribe a selective serotonin reuptake inhibitor and review in 2 weeks in primary care', false, 'Ruled out because this is inadequate for acute psychosis, which requires urgent psychiatric input, not a delayed primary care review.', 3),
('cd000000-0000-0000-0000-000000000041', 'D', 'Discharge home with health visitor follow-up only', false, 'Ruled out because this is unsafe given acute psychotic symptoms and risk to both mother and baby.', 4),
('cd000000-0000-0000-0000-000000000041', 'E', 'Advise this is postnatal depression and start routine outpatient counselling', false, 'Ruled out because this underestimates the severity; psychotic features indicate puerperal psychosis, not straightforward depression.', 5),
('cd000000-0000-0000-0000-000000000042', 'A', 'Stop breastfeeding from the affected breast immediately to allow it to heal', false, 'Ruled out because continuing milk removal from the affected breast is recommended, as stopping increases the risk of worsening milk stasis and abscess formation.', 1),
('cd000000-0000-0000-0000-000000000042', 'B', 'Arrange immediate incision and drainage in theatre', false, 'Ruled out because this is not indicated in the absence of a fluctuant abscess.', 2),
('cd000000-0000-0000-0000-000000000042', 'C', 'Continue breastfeeding (or expressing) from the affected breast, and start oral flucloxacillin if symptoms do not improve with continued milk removal', true, 'Correct. Mastitis is managed by continuing effective milk removal from the affected breast, adding antibiotics if there is no improvement or systemic infective features.', 3),
('cd000000-0000-0000-0000-000000000042', 'D', 'Reassure with no treatment, as this will resolve without any intervention', false, 'Ruled out because untreated mastitis can progress to a breast abscess; antibiotics are needed if it does not settle with milk removal.', 4),
('cd000000-0000-0000-0000-000000000042', 'E', 'Advise formula feeding permanently and cabbage leaves as the only treatment', false, 'Ruled out because this is not the recommended definitive management; effective milk removal from the affected breast is key.', 5),
('cd000000-0000-0000-0000-000000000043', 'A', 'No specific VTE prophylaxis is required after caesarean section', false, 'Ruled out because caesarean section itself is a risk factor for VTE, particularly with additional risk factors such as obesity and reduced mobility present here.', 1),
('cd000000-0000-0000-0000-000000000043', 'B', 'Aspirin alone is sufficient VTE prophylaxis', false, 'Ruled out because aspirin is not the standard prophylaxis for postpartum VTE; low molecular weight heparin is the standard agent used.', 2),
('cd000000-0000-0000-0000-000000000043', 'C', 'Full-dose therapeutic anticoagulation is required in all postpartum women', false, 'Ruled out because prophylactic-dose anticoagulation is standard unless there is a treatment-dose indication, such as a confirmed VTE.', 3),
('cd000000-0000-0000-0000-000000000043', 'D', 'Strict bed rest to reduce the risk of bleeding complications', false, 'Ruled out because immobility itself increases VTE risk; early mobilisation is encouraged, not bed rest.', 4),
('cd000000-0000-0000-0000-000000000043', 'E', 'Prophylactic low molecular weight heparin', true, 'Correct. Caesarean section, obesity, and reduced mobility are recognised risk factors for postpartum VTE, warranting prophylactic low molecular weight heparin in addition to early mobilisation.', 5),
('cd000000-0000-0000-0000-000000000044', 'A', 'The combined pill is safe to prescribe, as her BMI and smoking status are normal', false, 'Ruled out because migraine with aura is an absolute contraindication regardless of BMI or smoking status.', 1),
('cd000000-0000-0000-0000-000000000044', 'B', 'The combined oral contraceptive pill is contraindicated due to her migraine with aura, and an alternative method should be offered', true, 'Correct. Migraine with aura is a UKMEC category 4 (absolute) contraindication to combined hormonal contraception due to an increased risk of ischaemic stroke, regardless of other risk factors.', 2),
('cd000000-0000-0000-0000-000000000044', 'C', 'The combined pill can be started as long as she takes low-dose aspirin alongside it', false, 'Ruled out because this is not a recognised mitigation; migraine with aura remains an absolute contraindication.', 3),
('cd000000-0000-0000-0000-000000000044', 'D', 'Migraine with aura only becomes a contraindication if she is over the age of 35', false, 'Ruled out because migraine with aura is a contraindication at any age, not only in women over 35.', 4),
('cd000000-0000-0000-0000-000000000044', 'E', 'The combined pill is only contraindicated if she has more than four migraine episodes per month', false, 'Ruled out because frequency does not remove the aura-related contraindication; the presence of aura itself is the key factor.', 5),
('cd000000-0000-0000-0000-000000000045', 'A', 'Reassure that no action is needed, as desogestrel has a 12-hour window and 14 hours late is still within it', false, 'Ruled out because 14 hours exceeds the 12-hour missed pill window for the desogestrel-only pill, so this does count as a missed pill.', 1),
('cd000000-0000-0000-0000-000000000045', 'B', 'Advise she should stop taking the pill for 7 days before restarting', false, 'Ruled out because this is not the correct approach for a missed progestogen-only pill dose.', 2),
('cd000000-0000-0000-0000-000000000045', 'C', 'Advise emergency contraception is never indicated when only a progestogen-only pill dose has been missed', false, 'Ruled out because emergency contraception should be considered given the unprotected intercourse occurring after a missed dose outside the window.', 3),
('cd000000-0000-0000-0000-000000000045', 'D', 'This counts as a missed pill because the delay exceeded the 12-hour window; she should take the missed pill now, continue future pills as normal, use additional contraception (e.g. condoms) for the next 48 hours, and consider emergency contraception for the unprotected intercourse', true, 'Correct. The desogestrel-only pill has a 12-hour missed pill window; a delay of 14 hours exceeds this, so additional precautions and consideration of emergency contraception are needed.', 4),
('cd000000-0000-0000-0000-000000000045', 'E', 'Advise that no additional contraceptive precautions are needed as long as she resumes her normal pill time tomorrow', false, 'Ruled out because additional precautions are still needed for 48 hours after a late dose that exceeded the missed pill window.', 5),
('cd000000-0000-0000-0000-000000000046', 'A', 'Levonorgestrel', false, 'Ruled out because levonorgestrel emergency contraception is only licensed for use up to 72 hours after intercourse, making it unsuitable at 90 hours.', 1),
('cd000000-0000-0000-0000-000000000046', 'B', 'Combined oral contraceptive pill taken as a double dose', false, 'Ruled out because this is not a recognised or appropriate emergency contraception regimen.', 2),
('cd000000-0000-0000-0000-000000000046', 'C', 'Reassure that no emergency contraception is effective beyond 72 hours', false, 'Ruled out because this is factually incorrect; ulipristal acetate remains effective up to 120 hours.', 3),
('cd000000-0000-0000-0000-000000000046', 'D', 'Ulipristal acetate', true, 'Correct. Ulipristal acetate is licensed for use up to 120 hours after unprotected intercourse, making it suitable at 90 hours when levonorgestrel is no longer licensed and a copper IUD is declined.', 4),
('cd000000-0000-0000-0000-000000000046', 'E', 'Advise that emergency contraception is not needed as pregnancy risk is negligible after 72 hours', false, 'Ruled out because pregnancy risk remains present and should still be addressed with appropriate emergency contraception.', 5),
('cd000000-0000-0000-0000-000000000047', 'A', 'Increased risk of pelvic infection in the first 20 days after insertion', true, 'Correct. There is a small increased risk of pelvic infection in the first 20 days after intrauterine device insertion, related to the insertion procedure itself rather than the device long-term.', 1),
('cd000000-0000-0000-0000-000000000047', 'B', 'Guaranteed protection against sexually transmitted infections', false, 'Ruled out because intrauterine devices do not protect against sexually transmitted infections; condom use should still be advised.', 2),
('cd000000-0000-0000-0000-000000000047', 'C', 'Permanent infertility once the device is removed', false, 'Ruled out because fertility returns promptly to normal after removal of an intrauterine device.', 3),
('cd000000-0000-0000-0000-000000000047', 'D', 'Requirement for the device to be replaced every 3 months', false, 'Ruled out because copper intrauterine devices typically remain effective for 5-10 years depending on the device type, not 3 months.', 4),
('cd000000-0000-0000-0000-000000000047', 'E', 'Contraindication in women who have never been pregnant', false, 'Ruled out because nulliparity is not a contraindication to intrauterine device use.', 5),
('cd000000-0000-0000-0000-000000000048', 'A', 'Day 2 follicle-stimulating hormone level only', false, 'Ruled out because this assesses ovarian reserve rather than confirming whether ovulation has occurred in a given cycle.', 1),
('cd000000-0000-0000-0000-000000000048', 'B', 'Mid-luteal (day 21) serum progesterone level', true, 'Correct. Serum progesterone measured 7 days before the expected next period (day 21 in a 28-day cycle) is the standard test used to confirm ovulation.', 2),
('cd000000-0000-0000-0000-000000000048', 'C', 'Hysterosalpingogram', false, 'Ruled out because this assesses tubal patency, not ovulatory status.', 3),
('cd000000-0000-0000-0000-000000000048', 'D', 'Laparoscopy and dye test as the first-line investigation', false, 'Ruled out because this is more invasive and is not first-line for assessing ovulation.', 4),
('cd000000-0000-0000-0000-000000000048', 'E', 'Endometrial biopsy', false, 'Ruled out because this is not the standard first-line test for confirming ovulation.', 5),
('cd000000-0000-0000-0000-000000000049', 'A', 'Immediate referral for in vitro fertilisation', false, 'Ruled out because this is premature before trying first-line ovulation induction with letrozole or clomifene.', 1),
('cd000000-0000-0000-0000-000000000049', 'B', 'Metformin alone as first-line treatment for ovulation induction', false, 'Ruled out because metformin has an adjunctive role in some cases but is not preferred first-line over letrozole/clomifene for ovulation induction alone.', 2),
('cd000000-0000-0000-0000-000000000049', 'C', 'Gonadotrophin injections as first-line treatment', false, 'Ruled out because gonadotrophins are reserved as second-line treatment if clomifene or letrozole fail.', 3),
('cd000000-0000-0000-0000-000000000049', 'D', 'Laparoscopic ovarian drilling as first-line treatment', false, 'Ruled out because this is considered as a further option after failed medical ovulation induction, not as first-line treatment.', 4),
('cd000000-0000-0000-0000-000000000049', 'E', 'Letrozole (or clomifene) as first-line ovulation induction', true, 'Correct. In women with PCOS and anovulatory subfertility, letrozole or clomifene citrate is used as first-line pharmacological ovulation induction.', 5),
('cd000000-0000-0000-0000-000000000050', 'A', 'Immediate return of fertility within days of stopping the injection', false, 'Ruled out because return of fertility after stopping this method can be delayed, sometimes up to 12 months, unlike most other reversible methods.', 1),
('cd000000-0000-0000-0000-000000000050', 'B', 'Increased risk of ectopic pregnancy compared with no contraception', false, 'Ruled out because this is not a recognised specific concern with this method, which is highly effective at preventing pregnancy overall.', 2),
('cd000000-0000-0000-0000-000000000050', 'C', 'Reduction in bone mineral density with prolonged use', true, 'Correct. Depot medroxyprogesterone acetate is associated with a reversible reduction in bone mineral density with prolonged use, requiring periodic review.', 3),
('cd000000-0000-0000-0000-000000000050', 'D', 'Requirement for daily administration', false, 'Ruled out because this is an injectable given every 12-13 weeks, not a daily method.', 4),
('cd000000-0000-0000-0000-000000000050', 'E', 'Guaranteed weight loss during treatment', false, 'Ruled out because weight gain, not weight loss, is the more commonly reported concern with this method.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('cd000000-0000-0000-0000-000000000001', 'Clonus, severe headache and epigastric pain (indicating hepatic involvement) are signs of severe pre-eclampsia and impending eclampsia.', 1),
('cd000000-0000-0000-0000-000000000001', 'Magnesium sulfate is used for both prevention and treatment of eclamptic seizures in severe pre-eclampsia.', 2),
('cd000000-0000-0000-0000-000000000001', 'The definitive treatment of pre-eclampsia is delivery, but maternal stabilisation (BP control, magnesium sulfate) takes priority before delivery is expedited.', 3),
('cd000000-0000-0000-0000-000000000002', 'NICE diagnostic thresholds for gestational diabetes: fasting glucose 5.6 mmol/L or above, or 2-hour glucose 7.8 mmol/L or above on a 75g OGTT; only one abnormal value is needed for diagnosis.', 1),
('cd000000-0000-0000-0000-000000000002', 'Risk factors warranting OGTT screening include BMI over 30, previous macrosomic baby, previous gestational diabetes, family history of diabetes, and certain high-risk ethnic backgrounds.', 2),
('cd000000-0000-0000-0000-000000000002', 'Confirmed gestational diabetes should prompt referral to a joint diabetes-antenatal clinic for dietary advice and glucose monitoring, with medication added if targets are not met.', 3),
('cd000000-0000-0000-0000-000000000003', 'A symphysis-fundal height measurement more than 3cm below that expected for gestational age warrants referral for ultrasound biometry.', 1),
('cd000000-0000-0000-0000-000000000003', 'Umbilical artery Doppler assessment helps identify placental insufficiency as a cause of fetal growth restriction.', 2),
('cd000000-0000-0000-0000-000000000003', 'Serial growth scans and Dopplers guide timing of delivery in confirmed fetal growth restriction, balancing the risks of prematurity against continued growth restriction in utero.', 3),
('cd000000-0000-0000-0000-000000000004', 'Digital vaginal examination is contraindicated in suspected placenta praevia until placental location is confirmed, as it can trigger severe haemorrhage.', 1),
('cd000000-0000-0000-0000-000000000004', 'Placenta praevia classically causes painless vaginal bleeding, in contrast to the painful bleeding typical of placental abruption.', 2),
('cd000000-0000-0000-0000-000000000004', 'Confirmed major placenta praevia usually mandates elective caesarean section, with timing depending on bleeding episodes and gestation.', 3),
('cd000000-0000-0000-0000-000000000005', 'Rhesus-negative women without anti-D antibodies receive routine antenatal anti-D prophylaxis (commonly at 28 weeks) to reduce the risk of sensitisation.', 1),
('cd000000-0000-0000-0000-000000000005', 'Anti-D immunoglobulin should also be given after any potentially sensitising event (e.g. bleeding, trauma, invasive procedures) and again after delivery if the baby is Rh-positive.', 2),
('cd000000-0000-0000-0000-000000000005', 'Once anti-D antibodies have already formed (sensitisation has occurred), prophylactic anti-D immunoglobulin is no longer effective.', 3),
('cd000000-0000-0000-0000-000000000006', 'Reduced fetal movements after 28 weeks gestation should prompt urgent assessment, starting with CTG to assess fetal wellbeing.', 1),
('cd000000-0000-0000-0000-000000000006', 'If CTG is normal but concern remains, or risk factors for fetal growth restriction are present, ultrasound assessment of growth and liquor volume should follow.', 2),
('cd000000-0000-0000-0000-000000000006', 'Reduced fetal movements can be an early warning sign of placental insufficiency and increased stillbirth risk.', 3),
('cd000000-0000-0000-0000-000000000007', 'Sudden severe unilateral pelvic pain with signs of haemodynamic compromise in a woman with a positive pregnancy test suggests a ruptured ectopic pregnancy until proven otherwise.', 1),
('cd000000-0000-0000-0000-000000000007', 'Ruptured ectopic pregnancy with haemodynamic instability is a surgical emergency requiring resuscitation and urgent laparoscopy, not medical management.', 2),
('cd000000-0000-0000-0000-000000000007', 'Previous pelvic infection (e.g. chlamydia) is a recognised risk factor for ectopic pregnancy due to tubal damage.', 3),
('cd000000-0000-0000-0000-000000000008', 'Threatened miscarriage describes vaginal bleeding in early pregnancy with a closed cervix and a confirmed viable intrauterine pregnancy on ultrasound.', 1),
('cd000000-0000-0000-0000-000000000008', 'Inevitable miscarriage is characterised by an open cervix with bleeding, while a viable pregnancy may still be present at that point.', 2),
('cd000000-0000-0000-0000-000000000008', 'Reassurance and safety-netting advice (returning if bleeding worsens or pain develops) is appropriate management for threatened miscarriage.', 3),
('cd000000-0000-0000-0000-000000000009', 'Management options for missed miscarriage include expectant, medical (misoprostol), and surgical management, chosen based on patient preference and clinical factors.', 1),
('cd000000-0000-0000-0000-000000000009', 'Expectant management typically involves waiting up to two weeks and confirming completion with a urine pregnancy test at three weeks.', 2),
('cd000000-0000-0000-0000-000000000009', 'Anti-D immunoglobulin should be considered for Rhesus-negative women undergoing surgical management of miscarriage.', 3),
('cd000000-0000-0000-0000-000000000010', 'Hyperemesis gravidarum is diagnosed by the triad of more than 5% pre-pregnancy weight loss, dehydration, and electrolyte imbalance/ketonuria, distinguishing it from normal pregnancy sickness.', 1),
('cd000000-0000-0000-0000-000000000010', 'First-line antiemetics in pregnancy include cyclizine, promethazine, or prochlorperazine, with ondansetron and metoclopramide as alternatives used with some caution.', 2),
('cd000000-0000-0000-0000-000000000010', 'IV fluid replacement (with thiamine supplementation if vomiting is prolonged) is required for women unable to tolerate oral intake.', 3),
('cd000000-0000-0000-0000-000000000011', $x$Molar pregnancy classically presents with hyperemesis, vaginal bleeding, a uterus large for dates, and markedly elevated beta-hCG with a 'snowstorm' appearance on ultrasound.$x$, 1),
('cd000000-0000-0000-0000-000000000011', 'Management is surgical evacuation followed by registration with a specialist trophoblastic disease centre for serial hCG monitoring to detect persistent or malignant trophoblastic disease.', 2),
('cd000000-0000-0000-0000-000000000011', 'Effective contraception is advised during the follow-up period because a new pregnancy would confound hCG monitoring.', 3),
('cd000000-0000-0000-0000-000000000012', 'Pregnancy of unknown location refers to a positive pregnancy test with no intrauterine or extrauterine pregnancy seen on ultrasound; management is guided by serial beta-hCG measurements.', 1),
('cd000000-0000-0000-0000-000000000012', 'A rise of 63% or more over 48 hours is typically consistent with a normally progressing intrauterine pregnancy, while a slower rise or plateau raises suspicion of ectopic pregnancy.', 2),
('cd000000-0000-0000-0000-000000000012', 'A falling beta-hCG suggests a failing pregnancy, but must still be followed to resolution to exclude ectopic pregnancy.', 3),
('cd000000-0000-0000-0000-000000000013', 'Postmenopausal bleeding is a red-flag symptom requiring urgent (2-week wait) referral for investigation to exclude endometrial cancer.', 1),
('cd000000-0000-0000-0000-000000000013', 'Obesity, diabetes, and unopposed oestrogen exposure (including tamoxifen use) are recognised risk factors for endometrial cancer.', 2),
('cd000000-0000-0000-0000-000000000013', 'Transvaginal ultrasound measuring endometrial thickness is the first-line investigation; a thickened endometrium warrants endometrial biopsy.', 3),
('cd000000-0000-0000-0000-000000000014', 'Persistent bloating, early satiety, and abdominal distension in a woman over 50 are red-flag symptoms for ovarian cancer and warrant CA125 testing.', 1),
('cd000000-0000-0000-0000-000000000014', 'The Risk of Malignancy Index combines CA125 level, ultrasound features, and menopausal status to guide referral to specialist gynaecological oncology services.', 2),
('cd000000-0000-0000-0000-000000000014', 'Complex, solid, or multiloculated ovarian masses with elevated CA125 require urgent specialist assessment rather than routine management.', 3),
('cd000000-0000-0000-0000-000000000015', 'The UK cervical screening programme uses HPV primary testing; if HPV positive, cytology is examined, and abnormal cytology (dyskaryosis) triggers colposcopy referral.', 1),
('cd000000-0000-0000-0000-000000000015', 'High-grade dyskaryosis on cytology requires prompt colposcopic assessment and biopsy to identify and treat cervical intraepithelial neoplasia before progression to invasive cancer.', 2),
('cd000000-0000-0000-0000-000000000015', 'HPV vaccination is preventive and has no role in treating an established infection or an existing cervical abnormality.', 3),
('cd000000-0000-0000-0000-000000000016', 'A persistent vulval lump, ulcer, or lesion that fails to respond to treatment in an older woman is a red-flag symptom for vulval cancer requiring urgent referral.', 1),
('cd000000-0000-0000-0000-000000000016', 'Lichen sclerosus is a recognised risk factor for vulval squamous cell carcinoma and should prompt a lower threshold for biopsy of any new or changing lesion.', 2),
('cd000000-0000-0000-0000-000000000016', 'Diagnosis of vulval cancer is confirmed by biopsy; treatment usually involves surgical excision, with lymph node assessment depending on depth of invasion.', 3),
('cd000000-0000-0000-0000-000000000017', 'Postmenopausal ovarian cysts with complex features (septations, solid areas, papillary projections) carry a higher risk of malignancy than simple, thin-walled cysts.', 1),
('cd000000-0000-0000-0000-000000000017', 'The Risk of Malignancy Index (combining menopausal status, ultrasound score, and CA125) helps determine which women need specialist gynaecological oncology referral.', 2),
('cd000000-0000-0000-0000-000000000017', 'Simple, small, unilocular ovarian cysts in postmenopausal women can often be managed conservatively with surveillance, unlike complex cysts.', 3),
('cd000000-0000-0000-0000-000000000018', 'Tamoxifen has an oestrogenic effect on the endometrium and increases the risk of endometrial hyperplasia and cancer; any postmenopausal bleeding in a woman taking tamoxifen requires urgent investigation.', 1),
('cd000000-0000-0000-0000-000000000018', 'Postmenopausal bleeding always warrants urgent referral for transvaginal ultrasound assessment of endometrial thickness, regardless of a suspected benign cause.', 2),
('cd000000-0000-0000-0000-000000000018', 'Decisions about continuing or stopping tamoxifen should involve the oncology team and are separate from the urgent need to investigate abnormal bleeding.', 3),
('cd000000-0000-0000-0000-000000000019', 'Cord prolapse is an obstetric emergency causing cord compression and fetal hypoxia; immediate management is to elevate the presenting part off the cord and expedite delivery.', 1),
('cd000000-0000-0000-0000-000000000019', 'The cord should never be pushed back into the uterus; keeping it warm and moist while awaiting delivery is appropriate if delivery is not immediate.', 2),
('cd000000-0000-0000-0000-000000000019', 'Category 1 caesarean section is usually required unless vaginal delivery can be achieved immediately (e.g. a fully dilated multiparous woman).', 3),
('cd000000-0000-0000-0000-000000000020', $x$Shoulder dystocia is suspected when the 'turtle-neck sign' occurs and routine traction fails to deliver the shoulders after the head is born.$x$, 1),
('cd000000-0000-0000-0000-000000000020', $x$McRoberts manoeuvre is the first-line manoeuvre, followed by suprapubic pressure and internal manoeuvres (e.g. Rubin's, Wood's screw) if needed.$x$, 2),
('cd000000-0000-0000-0000-000000000020', 'Fundal pressure and excessive traction are contraindicated in shoulder dystocia due to the risk of uterine rupture and brachial plexus injury.', 3),
('cd000000-0000-0000-0000-000000000021', 'Late decelerations that recur with contractions, especially with reduced variability, are a pathological CTG feature suggesting fetal hypoxia and require prompt escalation.', 1),
('cd000000-0000-0000-0000-000000000021', 'Conservative measures (maternal repositioning, stopping oxytocin, IV fluids) should be tried while arranging further assessment such as fetal blood sampling.', 2),
('cd000000-0000-0000-0000-000000000021', 'Persistent pathological CTG findings that do not resolve with conservative measures warrant expedited delivery, often by emergency caesarean section.', 3),
('cd000000-0000-0000-0000-000000000022', 'Failure to progress in the first stage of labour (less than 2cm dilatation in 4 hours in a primigravida) prompts consideration of amniotomy and oxytocin augmentation if contractions are inadequate.', 1),
('cd000000-0000-0000-0000-000000000022', 'Partogram use with action lines helps identify delay in labour progress objectively and guide timely intervention.', 2),
('cd000000-0000-0000-0000-000000000022', 'Caesarean section is reserved for cases where augmentation fails, is contraindicated, or there are signs of fetal compromise.', 3),
('cd000000-0000-0000-0000-000000000023', $x$Placental abruption classically presents with painful vaginal bleeding, a tender 'woody-hard' uterus, and can be associated with fetal compromise.$x$, 1),
('cd000000-0000-0000-0000-000000000023', 'Risk factors for placental abruption include hypertension, smoking, cocaine use, previous abruption, and abdominal trauma.', 2),
('cd000000-0000-0000-0000-000000000023', 'In contrast to abruption, placenta praevia typically causes painless bleeding without uterine tenderness.', 3),
('cd000000-0000-0000-0000-000000000024', 'Uterine rupture should be suspected in a woman attempting VBAC who develops sudden severe pain, cessation of contractions, scar tenderness, and fetal bradycardia.', 1),
('cd000000-0000-0000-0000-000000000024', 'Uterine rupture is an obstetric emergency requiring immediate resuscitation and emergency laparotomy/caesarean section.', 2),
('cd000000-0000-0000-0000-000000000024', 'Previous caesarean section (particularly a classical/vertical incision) is the strongest risk factor for uterine rupture in a subsequent pregnancy.', 3),
('cd000000-0000-0000-0000-000000000025', 'NICE recommends the levonorgestrel intrauterine system (LNG-IUS) as first-line treatment for heavy menstrual bleeding when there is no identified structural or histological abnormality.', 1),
('cd000000-0000-0000-0000-000000000025', 'Non-hormonal options (tranexamic acid, NSAIDs) or combined hormonal contraception are alternatives if the LNG-IUS is declined or unsuitable.', 2),
('cd000000-0000-0000-0000-000000000025', 'Surgical options (endometrial ablation, hysterectomy) are reserved for women who have not responded to, or do not wish to try, medical management.', 3),
('cd000000-0000-0000-0000-000000000026', 'Uterine fibroids are common benign smooth muscle tumours that can cause heavy menstrual bleeding, pelvic pressure/pain, and a palpable pelvic mass.', 1),
('cd000000-0000-0000-0000-000000000026', 'Fibroid size, number, and location (submucosal, intramural, subserosal) influence symptoms and treatment choice.', 2),
('cd000000-0000-0000-0000-000000000026', 'Treatment options range from medical management (LNG-IUS, tranexamic acid) to surgical options (myomectomy, uterine artery embolisation, hysterectomy) depending on symptoms, fertility wishes, and fibroid characteristics.', 3),
('cd000000-0000-0000-0000-000000000027', 'Endometriosis classically presents with cyclical pelvic pain, dysmenorrhoea, deep dyspareunia, and sometimes subfertility; examination may reveal tenderness or nodularity in the posterior fornix.', 1),
('cd000000-0000-0000-0000-000000000027', 'Diagnostic laparoscopy with visualisation (and biopsy) of endometriotic lesions is the gold-standard investigation, as ultrasound can be normal even with significant disease.', 2),
('cd000000-0000-0000-0000-000000000027', 'Initial empirical management (analgesia, hormonal treatment such as the combined pill or progestogens) can be trialled before laparoscopy in straightforward cases.', 3),
('cd000000-0000-0000-0000-000000000028', 'PCOS is diagnosed using the Rotterdam criteria: at least 2 of oligo/anovulation, clinical or biochemical hyperandrogenism, and polycystic ovaries on ultrasound, after excluding other causes.', 1),
('cd000000-0000-0000-0000-000000000028', 'Other causes of irregular periods and hyperandrogenism (thyroid disease, hyperprolactinaemia, congenital adrenal hyperplasia) should be excluded before confirming PCOS.', 2),
('cd000000-0000-0000-0000-000000000028', 'Long-term management addresses menstrual irregularity, fertility, metabolic risk (insulin resistance, diabetes risk), and symptoms of hyperandrogenism.', 3),
('cd000000-0000-0000-0000-000000000029', 'Simple, unilocular, thin-walled ovarian cysts under 5cm in premenopausal women are usually functional/physiological and often resolve without intervention.', 1),
('cd000000-0000-0000-0000-000000000029', 'Conservative management with a follow-up ultrasound (often at 8-12 weeks) is appropriate for small simple cysts in premenopausal women.', 2),
('cd000000-0000-0000-0000-000000000029', 'Persistent, enlarging, or complex cysts, or those in postmenopausal women, warrant further assessment including CA125 and specialist referral.', 3),
('cd000000-0000-0000-0000-000000000030', $x$Adenomyosis is characterised by ectopic endometrial tissue within the myometrium, causing a diffusely enlarged, tender, 'boggy' uterus with dysmenorrhoea and menorrhagia.$x$, 1),
('cd000000-0000-0000-0000-000000000030', 'Ultrasound features of adenomyosis include a globular uterus, an indistinct endometrial-myometrial junction, and myometrial cysts, distinguishing it from discrete fibroids.', 2),
('cd000000-0000-0000-0000-000000000030', 'Management options include the LNG-IUS, other hormonal treatments, and hysterectomy for definitive treatment in women who have completed childbearing.', 3),
('cd000000-0000-0000-0000-000000000031', 'Pelvic inflammatory disease is a clinical diagnosis, and empirical antibiotic treatment should be started promptly (without waiting for swab results) to reduce the risk of long-term complications such as tubal infertility and chronic pelvic pain.', 1),
('cd000000-0000-0000-0000-000000000031', 'Cervical excitation and bilateral adnexal tenderness with a compatible history are key clinical features supporting a diagnosis of PID.', 2),
('cd000000-0000-0000-0000-000000000031', 'Sexual partners should be traced and treated, and patients advised to avoid intercourse until treatment is completed.', 3),
('cd000000-0000-0000-0000-000000000032', 'Ovarian torsion presents with sudden severe unilateral pelvic pain, often with nausea/vomiting, and is a surgical emergency due to the risk of ovarian ischaemia and necrosis.', 1),
('cd000000-0000-0000-0000-000000000032', 'Risk factors include ovarian cysts or masses (e.g. dermoid cysts) that increase ovarian mobility.', 2),
('cd000000-0000-0000-0000-000000000032', 'Absent or reduced blood flow on Doppler ultrasound supports the diagnosis, but a normal Doppler does not exclude torsion; clinical suspicion should still prompt urgent laparoscopy.', 3),
('cd000000-0000-0000-0000-000000000033', $x$Bartholin's abscess arises from infection of the Bartholin's gland duct, presenting as a tender, fluctuant swelling at the posterior introitus, typically unilateral.$x$, 1),
('cd000000-0000-0000-0000-000000000033', 'Management includes incision and drainage (often with word catheter placement or marsupialisation) plus antibiotics if there is surrounding cellulitis.', 2),
('cd000000-0000-0000-0000-000000000033', $x$Recurrent Bartholin's abscesses may require marsupialisation to create a permanent drainage opening and reduce recurrence.$x$, 3),
('cd000000-0000-0000-0000-000000000034', 'Toxic shock syndrome is a life-threatening condition caused by exotoxin-producing Staphylococcus aureus (or Streptococcus), classically associated with prolonged tampon use, presenting with fever, rash, hypotension, and multi-organ involvement.', 1),
('cd000000-0000-0000-0000-000000000034', 'Immediate management includes removing the source (e.g. tampon), aggressive fluid resuscitation, and broad-spectrum IV antibiotics.', 2),
('cd000000-0000-0000-0000-000000000034', 'Women should be advised on safe tampon use (regular changing, alternating with pads) to reduce the risk of toxic shock syndrome.', 3),
('cd000000-0000-0000-0000-000000000035', 'Ruptured ovarian cysts causing minor haemoperitoneum in a haemodynamically stable woman can usually be managed conservatively with analgesia and observation.', 1),
('cd000000-0000-0000-0000-000000000035', 'Free fluid in the pouch of Douglas on ultrasound, in the context of sudden pain and a collapsed cyst, is consistent with cyst rupture rather than an ongoing significant bleed requiring surgery.', 2),
('cd000000-0000-0000-0000-000000000035', 'Surgical intervention (laparoscopy) is reserved for cases with haemodynamic instability, significant haemoperitoneum, or an uncertain diagnosis.', 3),
('cd000000-0000-0000-0000-000000000036', 'A tubo-ovarian abscess is a serious complication of pelvic inflammatory disease and should be suspected when symptoms fail to improve with standard oral antibiotic treatment.', 1),
('cd000000-0000-0000-0000-000000000036', 'Management involves admission for IV broad-spectrum antibiotics, with radiological (image-guided) drainage or surgical intervention considered if there is no response or if the abscess is large or rupture is suspected.', 2),
('cd000000-0000-0000-0000-000000000036', 'Untreated or ruptured tubo-ovarian abscess can lead to sepsis and generalised peritonitis, a life-threatening emergency.', 3),
('cd000000-0000-0000-0000-000000000037', 'The 4 Ts (Tone, Tissue, Trauma, Thrombin) provide a systematic framework for identifying the cause of postpartum haemorrhage.', 1),
('cd000000-0000-0000-0000-000000000037', $x$Uterine atony (poor uterine tone) is the most common cause of primary PPH, and the uterus classically feels soft and poorly contracted ('boggy') on examination.$x$, 2),
('cd000000-0000-0000-0000-000000000037', $x$Initial management of atony includes uterine massage ('rubbing up' the fundus) and uterotonic drugs (oxytocin, ergometrine, carboprost, misoprostol) in a stepwise escalation.$x$, 3),
('cd000000-0000-0000-0000-000000000038', 'Secondary postpartum haemorrhage (occurring between 24 hours and 6 weeks after delivery) is often caused by retained products of conception or endometritis, or both together.', 1),
('cd000000-0000-0000-0000-000000000038', 'Fever, uterine tenderness, and subinvolution alongside bleeding suggest infection (endometritis) requiring antibiotics in addition to any surgical management.', 2),
('cd000000-0000-0000-0000-000000000038', 'Surgical evacuation of retained products is indicated when ultrasound confirms retained tissue, especially with ongoing bleeding or infection.', 3),
('cd000000-0000-0000-0000-000000000039', 'Postpartum endometritis typically presents with fever, uterine tenderness, and offensive-smelling lochia, and is more common after caesarean section than vaginal delivery.', 1),
('cd000000-0000-0000-0000-000000000039', 'Risk factors include caesarean delivery, prolonged labour, prolonged rupture of membranes, and multiple vaginal examinations.', 2),
('cd000000-0000-0000-0000-000000000039', 'Treatment is with broad-spectrum IV antibiotics covering polymicrobial (including anaerobic) organisms, with evacuation of retained tissue if present.', 3),
('cd000000-0000-0000-0000-000000000040', 'Perineal tears are classified from first degree (skin only) to fourth degree (involving rectal mucosa), with third-degree tears involving the anal sphincter complex.', 1),
('cd000000-0000-0000-0000-000000000040', 'Third-degree tears are subdivided: 3a (less than 50% external sphincter thickness torn), 3b (more than 50% external sphincter thickness torn), and 3c (internal sphincter also torn).', 2),
('cd000000-0000-0000-0000-000000000040', 'Third- and fourth-degree tears require repair in theatre by an appropriately trained clinician, with follow-up to monitor for anal incontinence.', 3),
('cd000000-0000-0000-0000-000000000041', 'Puerperal (postpartum) psychosis is a psychiatric emergency, typically presenting within the first 2 weeks postpartum with rapid onset confusion, delusions, hallucinations, or mood disturbance.', 1),
('cd000000-0000-0000-0000-000000000041', $x$It differs from 'baby blues' (common, mild, self-limiting mood lability in the first week) and postnatal depression (more gradual onset, low mood without psychotic features).$x$, 2),
('cd000000-0000-0000-0000-000000000041', 'Urgent psychiatric assessment is required, often with admission to a specialist mother and baby unit to ensure the safety of both mother and infant.', 3),
('cd000000-0000-0000-0000-000000000042', 'Mastitis is usually caused by milk stasis (often due to poor latch or missed feeds), and management includes continued breastfeeding or expressing to maintain milk drainage.', 1),
('cd000000-0000-0000-0000-000000000042', 'Antibiotics (typically flucloxacillin, or erythromycin/clarithromycin if penicillin-allergic) are indicated if symptoms do not improve within 12-24 hours of effective milk removal, or if there are systemic signs of infection.', 2),
('cd000000-0000-0000-0000-000000000042', 'A fluctuant, tender breast mass suggests progression to a breast abscess, which requires incision and drainage rather than antibiotics alone.', 3),
('cd000000-0000-0000-0000-000000000043', 'Caesarean section, obesity, and reduced mobility are recognised risk factors for postpartum venous thromboembolism, and risk assessment should be performed for all women.', 1),
('cd000000-0000-0000-0000-000000000043', 'Prophylactic low molecular weight heparin, alongside early mobilisation and adequate hydration, is the mainstay of VTE prevention in high-risk postpartum women.', 2),
('cd000000-0000-0000-0000-000000000043', 'The duration of postpartum thromboprophylaxis depends on the number and severity of risk factors, ranging from 10 days to 6 weeks.', 3),
('cd000000-0000-0000-0000-000000000044', 'Migraine with aura is a UKMEC category 4 (absolute) contraindication to combined hormonal contraception due to an increased risk of ischaemic stroke.', 1),
('cd000000-0000-0000-0000-000000000044', 'Progestogen-only methods (POP, implant, injectable, IUS) are generally suitable alternatives for women with migraine with aura who need contraception.', 2),
('cd000000-0000-0000-0000-000000000044', 'Other absolute or relative contraindications to combined hormonal contraception include a history of VTE, certain cardiovascular disease, and smoking combined with age over 35.', 3),
('cd000000-0000-0000-0000-000000000045', $x$The desogestrel-only pill has a 12-hour missed pill window, longer than the traditional (levonorgestrel/norethisterone) progestogen-only pill's 3-hour window.$x$, 1),
('cd000000-0000-0000-0000-000000000045', 'If a progestogen-only pill is taken outside its missed pill window, additional contraceptive precautions (e.g. condoms) are advised for the following 2 days.', 2),
('cd000000-0000-0000-0000-000000000045', 'Emergency contraception should be considered if unprotected intercourse has occurred during a period when contraceptive cover may have been compromised.', 3),
('cd000000-0000-0000-0000-000000000046', 'Levonorgestrel emergency contraception is licensed for use up to 72 hours after unprotected intercourse, while ulipristal acetate is licensed for up to 120 hours.', 1),
('cd000000-0000-0000-0000-000000000046', 'The copper intrauterine device is the most effective form of emergency contraception and remains an option up to 5 days after intercourse, or up to 5 days after the earliest predicted ovulation.', 2),
('cd000000-0000-0000-0000-000000000046', 'Ulipristal acetate should be used with caution or avoided in women who have recently taken progestogens, and may reduce the effectiveness of subsequent hormonal contraception if started too soon afterward.', 3),
('cd000000-0000-0000-0000-000000000047', 'There is a small increased risk of pelvic infection in the first 20 days after intrauterine device insertion, related to the insertion procedure itself rather than the device long-term.', 1),
('cd000000-0000-0000-0000-000000000047', 'Intrauterine devices do not protect against sexually transmitted infections, so condom use should still be advised for STI protection.', 2),
('cd000000-0000-0000-0000-000000000047', 'Fertility returns promptly after removal of an intrauterine device, and copper IUDs can remain effective for 5-10 years depending on the device type.', 3),
('cd000000-0000-0000-0000-000000000048', 'Serum progesterone measured 7 days before the expected next period (day 21 in a 28-day cycle) is used to confirm ovulation, as a rise in progesterone follows ovulation.', 1),
('cd000000-0000-0000-0000-000000000048', 'Investigations for subfertility should assess both partners: semen analysis for the male, and ovulatory/tubal/ovarian reserve assessment for the female.', 2),
('cd000000-0000-0000-0000-000000000048', 'Referral for specialist fertility assessment is typically offered after 12 months of unprotected regular intercourse without conception (or sooner if risk factors are present).', 3),
('cd000000-0000-0000-0000-000000000049', 'In women with PCOS and anovulatory subfertility, letrozole (or clomifene citrate) is used as first-line pharmacological ovulation induction, alongside weight management advice if overweight.', 1),
('cd000000-0000-0000-0000-000000000049', 'Ovulation induction should be monitored (e.g. with ultrasound) due to the risk of multiple pregnancy, particularly with clomifene.', 2),
('cd000000-0000-0000-0000-000000000049', 'Second-line options after failed first-line induction include gonadotrophin injections or laparoscopic ovarian drilling.', 3),
('cd000000-0000-0000-0000-000000000050', 'Depot medroxyprogesterone acetate (DMPA) is associated with a reversible reduction in bone mineral density with prolonged use, and this should be reviewed periodically, particularly in women with other osteoporosis risk factors.', 1),
('cd000000-0000-0000-0000-000000000050', 'Return of fertility after stopping DMPA can be delayed, sometimes up to 12 months, unlike most other reversible contraceptive methods.', 2),
('cd000000-0000-0000-0000-000000000050', 'Weight gain is a recognised and relatively common side effect reported by users of DMPA.', 3);
